"""Write deploy.sh / deploy.bat into the target project.

Never overwrites an existing file — if the project already has a deploy script,
portal leaves it alone and says so.
"""

from __future__ import annotations

import os
import stat
from pathlib import Path


def _build_deploy_sh(compose_project: str, compose_files: list[Path]) -> str:
    f_flags = " ".join(f'-f "{f}"' for f in compose_files)
    return f"""#!/usr/bin/env bash
# generated by portal - safe to edit, portal will never overwrite it.
# Redeploys this project: stop stack, pull latest, rebuild image, start stack.
#
# Pinned to portal's own project name and compose override so this stays
# wired to the same containers, network, and Cloudflare Tunnel that
# `portal deploy` set up - a bare `docker compose up` would use a different
# project name, skip the override, and republish a host port instead.
set -euo pipefail

COMPOSE=(docker compose -p {compose_project} {f_flags})

echo "==> Stopping stack"
"${{COMPOSE[@]}}" down

echo "==> Pulling latest code"
git pull

echo "==> Building image"
"${{COMPOSE[@]}}" build

echo "==> Starting stack"
"${{COMPOSE[@]}}" up -d

echo "==> Pruning dangling images"
docker image prune -f

echo "==> Done"
"${{COMPOSE[@]}}" ps
"""


def _build_deploy_bat(compose_project: str, compose_files: list[Path]) -> str:
    f_flags = " ".join(f'-f "{f}"' for f in compose_files)
    return f"""@echo off
REM generated by portal - safe to edit, portal will never overwrite it.
REM Redeploys this project: stop stack, pull latest, rebuild image, start stack.
REM
REM Pinned to portal's own project name and compose override so this stays
REM wired to the same containers, network, and Cloudflare Tunnel that
REM `portal deploy` set up - a bare `docker compose up` would use a different
REM project name, skip the override, and republish a host port instead.
setlocal

set COMPOSE=docker compose -p {compose_project} {f_flags}

echo ==^> Stopping stack
%COMPOSE% down || goto :fail

echo ==^> Pulling latest code
git pull || goto :fail

echo ==^> Building image
%COMPOSE% build || goto :fail

echo ==^> Starting stack
%COMPOSE% up -d || goto :fail

echo ==^> Pruning dangling images
docker image prune -f

echo ==^> Done
%COMPOSE% ps
exit /b 0

:fail
echo Deploy failed.
exit /b 1
"""


def scaffold_deploy_scripts(
    project_path: Path, *, compose_project: str, compose_files: list[Path]
) -> list[str]:
    """Write whichever of deploy.sh/deploy.bat are missing.

    Both scripts are pinned to `compose_project` and `compose_files` (the same
    -p/-f portal itself uses) so a plain re-run stays wired to the tunnel
    instead of standing up a second, disconnected stack.

    Returns the names actually written, so the caller can report skips.
    """
    written: list[str] = []
    for name, body, executable in (
        ("deploy.sh", _build_deploy_sh(compose_project, compose_files), True),
        ("deploy.bat", _build_deploy_bat(compose_project, compose_files), False),
    ):
        target = project_path / name
        if target.exists():
            continue
        target.write_text(body, encoding="utf-8", newline="\n" if executable else None)
        if executable and os.name == "posix":
            target.chmod(target.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP)
        written.append(name)
    return written
